import java.util.Arrays;
import java.util.List;
import java.util.ArrayList;
import java.util.function.Predicate;

public class Exercise {
    public static <T> List<T> filterList(List<T> list, Predicate<T> predicate) {
        List<T> result = new ArrayList<>();
        for (T item : list) {
            if (predicate.test(item)) result.add(item);
        }
        return result;
    }

    public static void main(String[] args) {
        List<String> words = Arrays.asList("apple", "banana", "apricot", "cherry", "avocado");

        Predicate<String> startsWithA = s -> s.startsWith("a");
        Predicate<String> longerThan5 = s -> s.length() > 5;
        Predicate<String> isApple     = Predicate.isEqual("apple");

        System.out.println("Starts with A: " + filterList(words, startsWithA));
        // [apple, apricot, avocado]
        System.out.println("Starts with A AND > 5 chars: " + filterList(words, startsWithA.and(longerThan5)));
        // [apricot, avocado]
        System.out.println("Is exactly 'apple': " + filterList(words, isApple));
        // [apple]
        System.out.println("Starts with A OR is cherry: " + filterList(words, startsWithA.or(Predicate.isEqual("cherry"))));
        // [apple, apricot, avocado, cherry]
    }
}

