import java.util.function.Function;

public class Exercise {
    public static void main(String[] args) {
        Function<String, Integer> strLen  = s -> s.length();
        Function<Integer, Integer> doubleIt = n -> n * 2;
        Function<Integer, String>  toHex  = Integer::toHexString;

        // andThen: strLen -> doubleIt
        Function<String, Integer> lenThenDouble = strLen.andThen(doubleIt);
        System.out.println("'hello' -> len -> doubled: " + lenThenDouble.apply("hello")); // 10

        // andThen chaining: strLen -> doubleIt -> toHex
        Function<String, String> lenDoubleHex = strLen.andThen(doubleIt).andThen(toHex);
        System.out.println("'hello' -> len -> doubled -> hex: " + lenDoubleHex.apply("hello")); // a

        // compose: doubleIt.compose(strLen) = strLen first, then doubleIt
        Function<String, Integer> composed = doubleIt.compose(strLen);
        System.out.println("compose: " + composed.apply("world")); // 10

        // identity: returns the input unchanged
        Function<String, String> id = Function.identity();
        System.out.println("identity: " + id.apply("unchanged")); // unchanged
    }
}

