import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.function.Supplier;

public class Exercise {
    public static void main(String[] args) {
        Supplier<List<String>> listSupplier = () -> {
            List<String> list = new ArrayList<>();
            list.add("alpha");
            list.add("beta");
            list.add("gamma");
            return list;
        };

        System.out.println("Before get()");
        List<String> result = listSupplier.get();
        System.out.println("Got: " + result); // [alpha, beta, gamma]
        // Each call creates a fresh list:
        System.out.println("Same? " + (listSupplier.get() == result)); // false

        // Lazy initialization pattern:
        String cachedValue = null;
        Supplier<String> expensiveSupplier = () -> {
            System.out.println("(computing...)");
            return "ExpensiveResult";
        };
        System.out.println("Need value? Checking...");
        if (cachedValue == null) {
            cachedValue = expensiveSupplier.get(); // only computed here
        }
        System.out.println("Value: " + cachedValue);
        // Second access: no re-computation
        if (cachedValue == null) {
            cachedValue = expensiveSupplier.get();
        }
        System.out.println("Value again: " + cachedValue); // no "(computing...)" line
    }
}

