import java.util.function.Supplier;

public class Exercise {
    @SuppressWarnings("unchecked")
    public static <T> Supplier<T> memoize(Supplier<T> supplier) {
        Object[] cache = {null};
        boolean[] computed = {false};
        return () -> {
            if (!computed[0]) {
                cache[0] = supplier.get();
                computed[0] = true;
            }
            return (T) cache[0];
        };
    }

    public static void main(String[] args) {
        Supplier<String> expensiveOp = () -> {
            System.out.println("Running expensive operation...");
            return "CachedResult";
        };

        Supplier<String> memoized = memoize(expensiveOp);

        System.out.println(memoized.get()); // prints "Running expensive operation..." then "CachedResult"
        System.out.println(memoized.get()); // prints only "CachedResult" — no recomputation
        System.out.println(memoized.get()); // same
        System.out.println("All calls complete.");
    }
}

