import java.util.ArrayList;
import java.util.List;
import java.util.function.Predicate;

public class Exercise {
    static class User {
        String username, email;
        int age;
        User(String username, String email, int age) {
            this.username = username; this.email = email; this.age = age;
        }
        public String toString() { return username + "/" + email + "/" + age; }
    }

    static class ValidationRule<T> {
        final Predicate<T> predicate;
        final String errorMessage;
        ValidationRule(Predicate<T> predicate, String errorMessage) {
            this.predicate = predicate;
            this.errorMessage = errorMessage;
        }
    }

    static class Validator<T> {
        private final List<ValidationRule<T>> rules = new ArrayList<>();

        public Validator<T> addRule(Predicate<T> predicate, String errorMessage) {
            rules.add(new ValidationRule<>(predicate, errorMessage));
            return this;
        }

        public List<String> validate(T value) {
            List<String> errors = new ArrayList<>();
            for (ValidationRule<T> rule : rules) {
                if (!rule.predicate.test(value)) {
                    errors.add(rule.errorMessage);
                }
            }
            return errors;
        }
    }

    public static void main(String[] args) {
        Validator<User> validator = new Validator<User>()
            .addRule(u -> u.username != null && u.username.length() >= 3, "Username must be at least 3 chars")
            .addRule(u -> u.username != null && u.username.length() <= 20, "Username must be at most 20 chars")
            .addRule(u -> u.email != null && u.email.contains("@"), "Email must contain @")
            .addRule(u -> u.age >= 18, "Must be 18 or older")
            .addRule(u -> u.age <= 120, "Age must be realistic");

        User validUser   = new User("alice", "alice@example.com", 25);
        User invalidUser = new User("ab", "notanemail", 15);

        System.out.println("Valid user errors:   " + validator.validate(validUser));   // []
        System.out.println("Invalid user errors: " + validator.validate(invalidUser));
        // [Username must be at least 3 chars, Email must contain @, Must be 18 or older]
    }
}

