import java.util.Arrays;
import java.util.List;
import java.util.Optional;
import java.util.function.BinaryOperator;

public class Exercise {
    public static void main(String[] args) {
        List<Integer> numbers = Arrays.asList(1, 2, 3, 4, 5);
        List<String> words = Arrays.asList("banana", "apple", "cherry", "date");

        // Product using identity-based reduce (identity = 1 for multiplication)
        BinaryOperator<Integer> multiply = (a, b) -> a * b;
        int product = numbers.stream().reduce(1, multiply);
        System.out.println("Product: " + product); // 120

        // String joining with separator (no identity -> Optional)
        BinaryOperator<String> joinWithComma = (a, b) -> a + ", " + b;
        Optional<String> joined = words.stream().reduce(joinWithComma);
        System.out.println("Joined: " + joined.orElse("(empty)")); // banana, apple, cherry, date

        // Longest string (no identity -> Optional)
        BinaryOperator<String> longest = (a, b) -> a.length() >= b.length() ? a : b;
        Optional<String> longestWord = words.stream().reduce(longest);
        System.out.println("Longest: " + longestWord.orElse("(empty)")); // banana or cherry (both 6)

        // Empty list: Optional is empty
        Optional<String> fromEmpty = List.<String>of().stream().reduce(joinWithComma);
        System.out.println("From empty: " + fromEmpty.isPresent()); // false
    }
}

