        Function<String, String> removePunctuation = s -> s.replaceAll("[^a-z0-9\\s]", "");

        Function<String, String> clean = trim.andThen(lower).andThen(removePunctuation);
        String cleaned = clean.apply(text);
        System.out.println("Cleaned: '" + cleaned + "'");
        // 'hello world hello java hello'

        String[] words = cleaned.split("\\s+");
        Map<String, Integer> freq = new HashMap<>();
        for (String w : words) {
            freq.merge(w, 1, Integer::sum);
        }
        System.out.println("Word frequencies: " + new TreeMap<>(freq));
        // {hello=3, java=1, world=1}
    }
}
